INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7414126, 1169115, 109387, '<td valign="top">This is super scary! I like the choice of the out of focus and how the foreground partially covers the ''monster''</td>', 'This is super scary! I like the choice of the out of focus and how the foreground partially covers the ''monster''', '2015-11-04 07:20:52.000000', NULL, 1),
(7414135, 1169288, 59029, '<td valign="top">I assume this is some steampunk thing but it''s not really translating well.  A guy in vintage clothing with a big smudge on his cheek, looking at his pocketwatch...we need more to work with.</td>', 'I assume this is some steampunk thing but it''s not really translating well.  A guy in vintage clothing with a big smudge on his cheek, looking at his pocketwatch...we need more to work with.', '2015-11-04 08:15:46.000000', NULL, 1),
(7414137, 1169355, 59029, '<td valign="top">spooky enough setting, now where''s the action?  Something needs to be taking place here and it isn''t.</td>', 'spooky enough setting, now where''s the action?  Something needs to be taking place here and it isn''t.', '2015-11-04 08:16:34.000000', NULL, 1),
