(7414145, 1169336, 59029, '<td valign="top">Who else could turn the Raft of the Medusa into such an incredible image? Congrats on the blue Christophe!</td>', 'Who else could turn the Raft of the Medusa into such an incredible image? Congrats on the blue Christophe!', '2015-11-04 08:22:13.000000', NULL, 1),
